import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.a6FUKr6c.js";const y=JSON.parse('{"title":"Channels & the Envelope","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels.md","filePath":"guide/channels.md","lastUpdated":1794463903000}'),t={name:"guide/channels.md"};function l(p,s,c,r,i,d){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="channels-the-envelope" tabindex="-1">Channels &amp; the Envelope <a class="header-anchor" href="#channels-the-envelope" aria-label="Permalink to &quot;Channels &amp; the Envelope&quot;">​</a></h1><p>A channel is anything a run can come from or talk to: a cron schedule, the REST API and MCP, generic webhooks, GitHub, an OpenClaw chat, the console. One contract covers all of them, so starting a run, answering where it came from and asking the owner for an approval work the same way on every transport.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">interface</span><span style="color:#DCE9F2;"> IChannel&lt;TInput = ChannelRequest, TOutput = Response&gt; {</span></span>
<span class="line"><span style="color:#8FD0F2;">    readonly</span><span style="color:#DCE9F2;"> name: string;</span></span>
<span class="line"><span style="color:#8FD0F2;">    readonly</span><span style="color:#DCE9F2;"> defaultAddress?: string;            </span><span style="color:#7F95A6;">// where emit()/approve() send when no address is given</span></span>
<span class="line"><span style="color:#DCE9F2;">    start?(ctx: ChannelContext): Promise&lt;void&gt;;  </span><span style="color:#7F95A6;">// background intake: cron ticks, sockets, polling</span></span>
<span class="line"><span style="color:#DCE9F2;">    stop?(): Promise&lt;void&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    in?(input: TInput, ctx: ChannelContext): Promise&lt;TOutput&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    out?(message: ChannelMessage, address: string, opts: ChannelSendOptions): Promise&lt;void&gt;; </span><span style="color:#7F95A6;">// idempotent on message.key</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ChannelRequest = { request: Request; subpath: string };  </span><span style="color:#7F95A6;">// the raw request, the raw path below /channels/&lt;name&gt;</span></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ChannelContext = { engine: IEngine; dispatch(envelope: ChannelDispatchEnvelope): Promise&lt;DispatchResult&gt; };</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ChannelMessage = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    kind: </span><span style="color:#E7C58C;">&#39;message&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;approval&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#DCE9F2;">    key: string;          </span><span style="color:#7F95A6;">// stable per logical message: the transport&#39;s dedupe key</span></span>
<span class="line"><span style="color:#DCE9F2;">    slot?: string;        </span><span style="color:#7F95A6;">// explicit named persistent message, where supported (GitHub)</span></span>
<span class="line"><span style="color:#DCE9F2;">    runId: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    title?: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    body: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    approvalId?: string;  </span><span style="color:#7F95A6;">// kind &#39;approval&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">    expiresAt?: Date;     </span><span style="color:#7F95A6;">// kind &#39;approval&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">    options?: ApprovalOption[]; </span><span style="color:#7F95A6;">// kind &#39;approval&#39; with options: { id, label, detail? }</span></span>
<span class="line"><span style="color:#DCE9F2;">    multiple?: boolean;   </span><span style="color:#7F95A6;">// kind &#39;approval&#39;, true when several options may be selected</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ChannelSendOptions = { signal: AbortSignal; trigger: TriggerEnvelope };</span></span></code></pre></div><p>The presence of <code>start</code>, <code>in</code> and <code>out</code> is a channel&#39;s only capability: <code>start</code>/<code>stop</code> run background intake (cron ticks, sockets, polling), <code>in</code> is the single inbound entry a transport feeds (the HTTP mount, tests), and <code>out</code> sends a message to an address the channel defines (<code>owner/repo#12</code> on GitHub, a chat recipient on OpenClaw). A channel&#39;s <code>name</code> follows the agent-name rule (<code>^[a-z0-9]+(-[a-z0-9]+)*$</code>) and is unique per engine. An out-only channel that always talks to one recipient sets <code>defaultAddress</code> (a non-empty string): <code>consoleChannel()</code> uses its name, the OpenClaw channel its <code>deliver.to</code>.</p><h2 id="registering-channels" tabindex="-1">Registering channels <a class="header-anchor" href="#registering-channels" aria-label="Permalink to &quot;Registering channels&quot;">​</a></h2><p>The engine holds the channel instances:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> triage = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Triage the issue in the payload.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [</span></span>
<span class="line"><span style="color:#DCE9F2;">        http.on(), </span><span style="color:#7F95A6;">// channel &#39;http&#39;, id &#39;http&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">        webhook.on(</span><span style="color:#E7C58C;">&#39;/issues&#39;</span><span style="color:#DCE9F2;">), </span><span style="color:#7F95A6;">// channel &#39;webhook&#39;, id &#39;webhook:/issues&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">        cron.on(</span><span style="color:#E7C58C;">&#39;*/30 * * * *&#39;</span><span style="color:#DCE9F2;">, { overlap: </span><span style="color:#E7C58C;">&#39;skip&#39;</span><span style="color:#DCE9F2;"> }), </span><span style="color:#7F95A6;">// channel &#39;cron&#39;, id &#39;cron:*/30 * * * *&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">    ],</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> engine = </span><span style="color:#8FD0F2;">new</span><span style="color:#DCE9F2;"> Engine({</span></span>
<span class="line"><span style="color:#DCE9F2;">    store: createMemoryStore(),</span></span>
<span class="line"><span style="color:#DCE9F2;">    agents: [triage],</span></span>
<span class="line"><span style="color:#7F95A6;">    // every subscribed channel must be registered (InvalidAgentDefinitionError otherwise)</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [httpChannel(), webhookChannel({ auth }), cronChannel()],</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><ul><li><code>new Engine({ channels })</code> refuses two channels with one name (<code>InvalidAgentDefinitionError</code>).</li><li><code>engine.start()</code> recovers runs, then calls every channel&#39;s <code>start(ctx)</code> in registration order; a throwing <code>start</code> stops the channels already started and rejects <code>engine.start()</code>. <code>engine.start({ channels: false })</code> starts none (a one-shot <a href="/guide/scheduler#one-shot-jobs">cron job</a> uses it).</li><li><code>engine.stop()</code> stops the poll and calls every <code>stop()</code>, resolving once all of them settled (await it before closing the store); <code>engine.drain()</code> does the same <strong>first</strong> (no new intake), then drains. A throwing <code>stop</code> goes to <code>onError</code> and the drain goes on.</li><li><code>ctx.dispatch(envelope)</code> is <code>engine.dispatch()</code> with <code>channel</code> set to the channel&#39;s own name: a channel cannot dispatch as another.</li><li>The name <code>agent</code> belongs to <code>agentChannel()</code> from <code>@chamvi/core</code> (no <code>in</code>, no <code>out</code>), the channel <a href="/guide/dispatch">dispatched runs</a> come in on. <code>@chamvi/app</code> contributes it, so a user channel named <code>agent</code> clashes at setup (<code>The channel &quot;agent&quot; is registered more than once.</code>).</li></ul><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to &quot;Subscriptions&quot;">​</a></h2><p>Every subscription builder accepts <code>concurrencyMaxRuns?: number | false</code>: a positive safe integer adds a shared-store execution ceiling for that subscription; <code>false</code> or omission adds none. It never bypasses the agent&#39;s own <code>concurrencyMaxRuns</code>. REST and MCP runs share the cap of <code>http.on()</code>. This is separate from concurrency keys, cron overlap and HTTP request rate limiting. See <a href="/guide/concurrency#shared-agent-and-subscription-ceilings">Concurrency</a>.</p><p>An agent subscribes to channels with <code>channels: ChannelSubscription[]</code>. Each channel package exports a builder named after its default channel; its <code>on()</code> makes subscriptions, and they are pure data, so an <a href="/guide/agent-folders">agent folder</a> imports them without an instance:</p><table tabindex="0"><thead><tr><th>Builder</th><th>Package</th><th>Channel</th><th>Id</th><th>Options</th></tr></thead><tbody><tr><td><code>http.on(opts?)</code></td><td><code>@chamvi/http</code></td><td><code>http</code> (REST) and <code>mcp</code></td><td><code>http</code></td><td><code>schema?</code>: a Standard Schema for the payload. At most one per agent; REST, the UI and MCP start runs through it</td></tr><tr><td><code>webhook.on(path, opts?)</code></td><td><code>@chamvi/http</code></td><td><code>webhook</code></td><td><code>webhook:&lt;path&gt;</code></td><td><code>path</code> (starts with <code>/</code>), <code>schema?</code>, <code>idempotencyKey?</code>, <code>concurrencyKey?</code>. Many per agent</td></tr><tr><td><code>cron.on(expression, opts?)</code></td><td><code>@chamvi/channel-cron</code></td><td><code>cron</code></td><td><code>cron:&lt;expression&gt;</code></td><td><code>timezone?</code>, <code>overlap?</code> (<code>skip</code> by default, <code>queue-one</code>, <code>allow</code>), <code>payload?</code>, <code>id?</code></td></tr><tr><td><code>github.on(events, opts?)</code></td><td><code>@chamvi/github</code></td><td><code>github</code></td><td><code>github:&lt;events&gt;</code></td><td><code>events</code> (<code>&#39;issues&#39;</code> or <code>&#39;issues.opened&#39;</code>, one or an array), <code>id?</code>, <code>filter?</code>, <code>idempotencyKey?</code> (default the delivery id), <code>concurrencyKey?</code> (default <code>&lt;owner&gt;/&lt;repo&gt;#&lt;number&gt;</code>). See <a href="/deployment/github-app">GitHub App</a></td></tr><tr><td><code>agent.on(opts?)</code></td><td><code>@chamvi/core</code></td><td><code>agent</code></td><td>the role (<code>default</code>)</td><td><code>role?</code>, <code>schema?</code>, <code>maxPerRun?</code> (default 100), <code>from?</code>, <code>maxDepth?</code> (default 1, at most 8), <code>idempotencyKey?</code>, <code>concurrencyKey?</code>. One per role; the opt-in for <a href="/guide/dispatch"><code>dispatch()</code> and <code>dispatchTo()</code></a></td></tr></tbody></table><p>A second instance of a channel (<code>cronChannel({ name: &#39;cron-eu&#39; })</code>) has its own <code>on()</code> bound to its name, so its subscriptions reach only it. Subscription ids must be unique per agent. The engine (constructor and <code>putAgent</code>) refuses a subscription naming a channel it does not hold, so register <code>httpChannel()</code> for <code>http.on()</code>, <code>cronChannel()</code> for <code>cron.on()</code>, and so on. With <a href="/guide/app"><code>@chamvi/app</code></a> the built-in modules register <code>agent</code>, <code>http</code>, <code>mcp</code>, <code>webhook</code> and <code>cron</code> for you.</p><p>A subscription may carry <code>concurrencyKey(payload)</code> and <code>idempotencyKey(payload)</code> functions; the channel that dispatches computes the envelope keys from them.</p><h2 id="the-envelope" tabindex="-1">The envelope <a class="header-anchor" href="#the-envelope" aria-label="Permalink to &quot;The envelope&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">/*</span></span>
<span class="line"><span style="color:#7F95A6;"> * Copyright (c) 2026.</span></span>
<span class="line"><span style="color:#7F95A6;"> * Author Peter Placzek (tada5hi)</span></span>
<span class="line"><span style="color:#7F95A6;"> * For the full copyright and license information,</span></span>
<span class="line"><span style="color:#7F95A6;"> * view the LICENSE file that was distributed with this source code.</span></span>
<span class="line"><span style="color:#7F95A6;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> { Artifact } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;../artifact/types.ts&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">/**</span></span>
<span class="line"><span style="color:#7F95A6;"> * Who started a run (or answered an approval), as an authenticator resolved</span></span>
<span class="line"><span style="color:#7F95A6;"> * it: a snapshot of identity and grants taken at dispatch, never a token.</span></span>
<span class="line"><span style="color:#7F95A6;"> * Revoking a grant later does not reach a run that already holds it.</span></span>
<span class="line"><span style="color:#7F95A6;"> */</span></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> Invoker = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    id: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /**</span></span>
<span class="line"><span style="color:#7F95A6;">     * The authenticator&#39;s label: \`@chamvi/http\`&#39;s staticTokens() sets</span></span>
<span class="line"><span style="color:#7F95A6;">     * &#39;token&#39; and authup() sets &#39;authup&#39;; oidc() keeps the kind its</span></span>
<span class="line"><span style="color:#7F95A6;">     * \`principal\` mapper returns (the docs use &#39;oidc&#39;); a custom authenticator</span></span>
<span class="line"><span style="color:#7F95A6;">     * or a direct dispatch may use its own (e.g. &#39;user&#39;).</span></span>
<span class="line"><span style="color:#7F95A6;">     */</span></span>
<span class="line"><span style="color:#DCE9F2;">    kind: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    name?: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    permissions: </span><span style="color:#8FD0F2;">readonly</span><span style="color:#DCE9F2;"> string[];</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">/**</span></span>
<span class="line"><span style="color:#7F95A6;"> * The run that dispatched this one. Only the engine-internal host sets it;</span></span>
<span class="line"><span style="color:#7F95A6;"> * a dispatch() envelope never carries one, so no caller forges lineage.</span></span>
<span class="line"><span style="color:#7F95A6;"> */</span></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> TriggerParent = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    kind: </span><span style="color:#E7C58C;">&#39;dispatch&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#DCE9F2;">    runId: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** The parent run&#39;s agent. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** The dispatch role of the child agent this run was started through. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    role: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    depth: number;</span></span>
<span class="line"><span style="color:#7F95A6;">    /**</span></span>
<span class="line"><span style="color:#7F95A6;">     * The one channel and address the dispatching code named for this run</span></span>
<span class="line"><span style="color:#7F95A6;">     * (\`dispatch(ctx, { source })\`): its outbound gate exempts that</span></span>
<span class="line"><span style="color:#7F95A6;">     * destination like a run&#39;s own source. Never from a generated dispatch tool.</span></span>
<span class="line"><span style="color:#7F95A6;">     */</span></span>
<span class="line"><span style="color:#DCE9F2;">    source?: TriggerSource;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">/** A channel and an address on it, as \`dispatch()\`&#39;s \`source\` names it. */</span></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> TriggerSource = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    address: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> TriggerEnvelope&lt;P = unknown&gt; = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    id: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** The id of the agent&#39;s subscription that started the run. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    trigger: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** The name of the channel the run came from. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    payload: P;</span></span>
<span class="line"><span style="color:#DCE9F2;">    idempotencyKey?: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    concurrencyKey?: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** Where the run came from on that channel (an issue, a thread, a caller); the channel defines it. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    address?: string;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** Files the run was started with, stored as artifacts of the run; the model gets them as file parts. */</span></span>
<span class="line"><span style="color:#DCE9F2;">    attachments?: Artifact[];</span></span>
<span class="line"><span style="color:#7F95A6;">    /**</span></span>
<span class="line"><span style="color:#7F95A6;">     * Who started the run; only ever set from an authenticator (never from a</span></span>
<span class="line"><span style="color:#7F95A6;">     * payload). Absent for runs a channel started without one (cron, webhooks). With an invoker the</span></span>
<span class="line"><span style="color:#7F95A6;">     * idempotency key is scoped to it, so only the same invoker&#39;s dispatch</span></span>
<span class="line"><span style="color:#7F95A6;">     * is deduplicated (and gets its own first run).</span></span>
<span class="line"><span style="color:#7F95A6;">     */</span></span>
<span class="line"><span style="color:#DCE9F2;">    invoker?: Invoker;</span></span>
<span class="line"><span style="color:#7F95A6;">    /** The run that dispatched this one; set only by dispatch(), never from engine.dispatch(). */</span></span>
<span class="line"><span style="color:#DCE9F2;">    parent?: TriggerParent;</span></span>
<span class="line"><span style="color:#DCE9F2;">    receivedAt: Date;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span></code></pre></div><p><code>dispatch()</code> takes the envelope without <code>id</code> and <code>receivedAt</code>; it fills in a random UUID and the current time. <code>trigger</code> is the subscription id (<code>&#39;http&#39;</code>, <code>&#39;webhook:/issues&#39;</code>, ...), <code>channel</code> the name of the channel the run came from (<code>&#39;mcp&#39;</code> for a run started through <code>http.on()</code> over MCP). <code>address</code> is where the run came from on that channel, as the channel defines it (the issue for GitHub, a chat recipient); it is stored on the run as <code>run.address</code> and is where <a href="#outbound-from-tools"><code>ctx.channels.findOne()</code></a> answers. An <code>idempotencyKey</code>, <code>concurrencyKey</code> or <code>address</code> above 255 characters or with a NUL is refused (<code>ValidationError</code>) before anything is written.</p><p>The engine renders the channel, subscription id and payload as a JSON block and makes it the run&#39;s first user message. The model sees exactly that; put what it needs into the payload.</p><p><code>invoker</code> is who started the run. Only a channel sets it, from its authenticated caller (<code>@chamvi/http</code> fills it from the principal), never from a payload. It is not part of the rendered block, so the model never sees it. See <a href="/guide/tools#restricting-tools-per-invoker">Restricting tools per invoker</a>.</p><p>Runs stored before channels existed (<code>source</code> and <code>thread</code> in the envelope) read back as <code>channel</code> and <code>address</code> from both repositories.</p><h2 id="outbound-from-tools" tabindex="-1">Outbound from tools <a class="header-anchor" href="#outbound-from-tools" aria-label="Permalink to &quot;Outbound from tools&quot;">​</a></h2><p>The engine never sends a message of its own. A tool sends through a channel:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> resolve = defineTool({</span></span>
<span class="line"><span style="color:#DCE9F2;">    description: </span><span style="color:#E7C58C;">&#39;Report the fix and tell the on-call channel.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    inputSchema: z.object({ summary: z.string() }),</span></span>
<span class="line"><span style="color:#8FD0F2;">    async</span><span style="color:#DCE9F2;"> execute({ summary }, { context }) {</span></span>
<span class="line"><span style="color:#7F95A6;">        // the run&#39;s source channel at its source address; undefined when that channel has no out</span></span>
<span class="line"><span style="color:#8FD0F2;">        await</span><span style="color:#DCE9F2;"> context.channels.findOne()?.emit({ body: summary });</span></span>
<span class="line"><span style="color:#7F95A6;">        // any registered channel with out; the address is required off the source channel</span></span>
<span class="line"><span style="color:#8FD0F2;">        await</span><span style="color:#DCE9F2;"> context.channels.findOneOrFail(</span><span style="color:#E7C58C;">&#39;console&#39;</span><span style="color:#DCE9F2;">).emit({ title: </span><span style="color:#E7C58C;">&#39;Resolved&#39;</span><span style="color:#DCE9F2;">, body: summary }, </span><span style="color:#E7C58C;">&#39;on-call&#39;</span><span style="color:#DCE9F2;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">        return</span><span style="color:#E7C58C;"> &#39;reported&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#DCE9F2;">    },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> function</span><span style="color:#DCE9F2;"> createEngine(model: LanguageModel) {</span></span>
<span class="line"><span style="color:#8FD0F2;">    return</span><span style="color:#8FD0F2;"> new</span><span style="color:#DCE9F2;"> Engine({</span></span>
<span class="line"><span style="color:#DCE9F2;">        store: createMemoryStore(),</span></span>
<span class="line"><span style="color:#DCE9F2;">        agents: [defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">            name: </span><span style="color:#E7C58C;">&#39;fixer&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            model,</span></span>
<span class="line"><span style="color:#DCE9F2;">            instructions: </span><span style="color:#E7C58C;">&#39;Fix the issue, then report it.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            tools: { resolve },</span></span>
<span class="line"><span style="color:#DCE9F2;">        })],</span></span>
<span class="line"><span style="color:#DCE9F2;">        channels: [consoleChannel()],</span></span>
<span class="line"><span style="color:#DCE9F2;">    });</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span></code></pre></div><ul><li><code>ctx.channels.findOne(name)</code> returns a handle on a registered channel with <code>out</code>, or <code>undefined</code> for an unknown name or a channel without <code>out</code>. Without a name it is the run&#39;s source channel, bound to its source address, so a tool answers where the run came from without knowing the channel (and gets <code>undefined</code> for a run from <code>http</code>, <code>mcp</code> or <code>cron</code>).</li><li><code>ctx.channels.findOneOrFail(name?)</code> is the same, but throws <code>ChannelNotFoundError</code> (<code>channel_not_found</code>) instead of returning <code>undefined</code>: use it for a channel the agent cannot work without.</li><li><code>ctx.channels.find()</code> returns a handle on every channel with <code>out</code>, in registration order.</li><li><code>handle.emit({ title?, body, key?, slot? }, address?)</code> sends through <code>out</code>. The address defaults to the source address on the source channel, else to the channel&#39;s <code>defaultAddress</code>; without either a missing address is a <code>validation_error</code> tool error.</li><li>An emit is an <a href="/guide/effect-tools">effect</a>: its key is <code>&lt;runId&gt;:emit:&lt;channel&gt;:&lt;sha256 of address and message&gt;</code> (or your <code>key</code>), recorded in the effect store, so identical emits of one step and a step redone after a crash send once. <code>out</code> gets the key as <code>message.key</code>, to dedupe on in the transport. A throwing <code>out</code> records nothing and is a tool error, so the next identical emit sends again.</li><li><code>emit</code> outside a tool call (in the tools factory) throws <code>InvalidRunStateError</code>: the tool call is the unit of retry.</li><li><code>handle.approve({ title, body?, options?, multiple?, timeoutMs?, address?, slot? })</code> asks the owner through the channel; see <a href="/guide/approvals">Approvals</a>.</li></ul><h3 id="named-message-slots" tabindex="-1">Named message slots <a class="header-anchor" href="#named-message-slots" aria-label="Permalink to &quot;Named message slots&quot;">​</a></h3><p>A transport can support a persistent message addressed by <code>slot</code>. GitHub uses it to create a comment once, then update it across runs; omit <code>slot</code> to append an ordinary comment. A slot is a non-empty, well-formed Unicode string without NUL characters, chosen explicitly on each <code>emit()</code> or channel <code>approve()</code> call. A single channel and agent can mix ordinary replies and several independent slots. Slot selection is separate from the per-delivery <code>key</code>, which still deduplicates retries. The effect key includes the slot when present, so identical text or custom keys aimed at different slots do not suppress each other. Approval slots are stored with the waiting run and retained on recovery. Other shipped transports currently ignore slot hints. See <a href="/deployment/github-app#persistent-status-comments">GitHub persistent status comments</a>.</p><h2 id="writing-a-channel" tabindex="-1">Writing a channel <a class="header-anchor" href="#writing-a-channel" aria-label="Permalink to &quot;Writing a channel&quot;">​</a></h2><p>A chat bridge with both directions:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> ChatPost = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    text: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    user: string</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">/** A chat bridge: messages in at POST /channels/chat, answers out to the chat&#39;s API. */</span></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> function</span><span style="color:#DCE9F2;"> chatChannel(options: { secret: string; apiUrl: string }): IChannel {</span></span>
<span class="line"><span style="color:#8FD0F2;">    return</span><span style="color:#DCE9F2;"> {</span></span>
<span class="line"><span style="color:#DCE9F2;">        name: </span><span style="color:#E7C58C;">&#39;chat&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">        // served by createHttpApp({ channels: [chat] }) at POST /channels/chat[/...]</span></span>
<span class="line"><span style="color:#8FD0F2;">        async</span><span style="color:#DCE9F2;"> in({ request }: ChannelRequest, ctx: ChannelContext): Promise&lt;Response&gt; {</span></span>
<span class="line"><span style="color:#7F95A6;">            // the http app never authenticates channel routes: check your own credentials</span></span>
<span class="line"><span style="color:#8FD0F2;">            if</span><span style="color:#DCE9F2;"> (request.headers.get(</span><span style="color:#E7C58C;">&#39;authorization&#39;</span><span style="color:#DCE9F2;">) !== </span><span style="color:#E7C58C;">\`Bearer </span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">options</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">secret</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;">) {</span></span>
<span class="line"><span style="color:#8FD0F2;">                return</span><span style="color:#8FD0F2;"> new</span><span style="color:#DCE9F2;"> Response(</span><span style="color:#8FD0F2;">null</span><span style="color:#DCE9F2;">, { status: </span><span style="color:#E7C58C;">401</span><span style="color:#DCE9F2;"> });</span></span>
<span class="line"><span style="color:#DCE9F2;">            }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">            // 413 above the limit</span></span>
<span class="line"><span style="color:#8FD0F2;">            const</span><span style="color:#DCE9F2;"> bytes = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> readRequestBody(request, { limit: </span><span style="color:#E7C58C;">64</span><span style="color:#DCE9F2;"> * </span><span style="color:#E7C58C;">1024</span><span style="color:#DCE9F2;"> });</span></span>
<span class="line"><span style="color:#8FD0F2;">            const</span><span style="color:#DCE9F2;"> post = JSON.parse(</span><span style="color:#8FD0F2;">new</span><span style="color:#DCE9F2;"> TextDecoder().decode(bytes)) </span><span style="color:#8FD0F2;">as</span><span style="color:#DCE9F2;"> ChatPost;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">            if</span><span style="color:#DCE9F2;"> (</span><span style="color:#8FD0F2;">typeof</span><span style="color:#DCE9F2;"> post.text !== </span><span style="color:#E7C58C;">&#39;string&#39;</span><span style="color:#DCE9F2;">) {</span></span>
<span class="line"><span style="color:#8FD0F2;">                throw</span><span style="color:#8FD0F2;"> new</span><span style="color:#DCE9F2;"> ValidationError(</span><span style="color:#E7C58C;">&#39;text is required.&#39;</span><span style="color:#DCE9F2;">);</span></span>
<span class="line"><span style="color:#DCE9F2;">            }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">            // dispatches as this channel (envelope channel &#39;chat&#39;), never as another</span></span>
<span class="line"><span style="color:#8FD0F2;">            const</span><span style="color:#DCE9F2;"> { runId } = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> ctx.dispatch({</span></span>
<span class="line"><span style="color:#DCE9F2;">                agent: </span><span style="color:#E7C58C;">&#39;helpdesk&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">                trigger: </span><span style="color:#E7C58C;">&#39;chat&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">                payload: post,</span></span>
<span class="line"><span style="color:#DCE9F2;">                address: post.channel,</span></span>
<span class="line"><span style="color:#DCE9F2;">            });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">            return</span><span style="color:#DCE9F2;"> Response.json({ runId }, { status: </span><span style="color:#E7C58C;">202</span><span style="color:#DCE9F2;"> });</span></span>
<span class="line"><span style="color:#DCE9F2;">        },</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">        // called for emit() and for approval requests; must be idempotent on message.key</span></span>
<span class="line"><span style="color:#8FD0F2;">        async</span><span style="color:#DCE9F2;"> out(message: ChannelMessage, address: string, opts: ChannelSendOptions): Promise&lt;void&gt; {</span></span>
<span class="line"><span style="color:#8FD0F2;">            const</span><span style="color:#DCE9F2;"> response = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> fetch(</span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">options</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">apiUrl</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">/messages\`</span><span style="color:#DCE9F2;">, {</span></span>
<span class="line"><span style="color:#DCE9F2;">                method: </span><span style="color:#E7C58C;">&#39;POST&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">                headers: { </span><span style="color:#E7C58C;">&#39;content-type&#39;</span><span style="color:#DCE9F2;">: </span><span style="color:#E7C58C;">&#39;application/json&#39;</span><span style="color:#DCE9F2;">, </span><span style="color:#E7C58C;">&#39;idempotency-key&#39;</span><span style="color:#DCE9F2;">: message.key },</span></span>
<span class="line"><span style="color:#DCE9F2;">                body: JSON.stringify({</span></span>
<span class="line"><span style="color:#DCE9F2;">                    channel: address,</span></span>
<span class="line"><span style="color:#DCE9F2;">                    text: [message.title, message.body].filter(Boolean).join(</span><span style="color:#E7C58C;">&#39;\\n&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#7F95A6;">                    // an approval carries its id and expiry: link to the UI</span></span>
<span class="line"><span style="color:#DCE9F2;">                    link: message.approvalId ?</span></span>
<span class="line"><span style="color:#E7C58C;">                        \`https://chamvi.example/ui/approvals?run=</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">message</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">runId</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">&amp;approval=</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">message</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">approvalId</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;"> :</span></span>
<span class="line"><span style="color:#8FD0F2;">                        undefined</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">                }),</span></span>
<span class="line"><span style="color:#DCE9F2;">                signal: opts.signal,</span></span>
<span class="line"><span style="color:#DCE9F2;">            });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">            // throw on failure: an emit records nothing, an approval is re-sent on the next poll</span></span>
<span class="line"><span style="color:#8FD0F2;">            if</span><span style="color:#DCE9F2;"> (</span><span style="color:#8FD0F2;">!</span><span style="color:#DCE9F2;">response.ok) {</span></span>
<span class="line"><span style="color:#8FD0F2;">                throw</span><span style="color:#8FD0F2;"> new</span><span style="color:#DCE9F2;"> Error(</span><span style="color:#E7C58C;">\`Chat answered </span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">response</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">status</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">.\`</span><span style="color:#DCE9F2;">);</span></span>
<span class="line"><span style="color:#DCE9F2;">            }</span></span>
<span class="line"><span style="color:#DCE9F2;">        },</span></span>
<span class="line"><span style="color:#DCE9F2;">    };</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span></code></pre></div><p>Rules for a channel:</p><ol><li><strong><code>in</code> checks its own credentials.</strong> <code>createHttpApp({ channels })</code> mounts <code>POST /channels/&lt;name&gt;</code> and everything below it for the listed channels, rate-limited but never authenticated by the app&#39;s authenticators. Read the body with <code>readRequestBody(request, { limit })</code> from <code>@chamvi/http</code> (413 above the limit); any thrown error renders through the app&#39;s JSON error handler.</li><li><strong><code>out</code> throws on failure.</strong> A failed emit records nothing; a failed approval message leaves <code>waiting.notifiedAt</code> unset and <code>tick()</code> re-sends it on every poll.</li><li><strong><code>out</code> is idempotent on <code>message.key</code>.</strong> A crash after a successful send but before the record re-sends with the same key; pass it to the transport (an <code>Idempotency-Key</code> header, a hidden marker) so the owner gets one message.</li><li><strong>Link to the approval.</strong> A message carries the approval id; link to the approval in the <a href="/guide/ui#approval-links">dashboard</a>, where the owner answers signed in.</li></ol><p><code>ChannelSendOptions</code> carries the call&#39;s <code>signal</code> and <code>trigger</code>, the run&#39;s stored envelope (e.g. to find the run&#39;s issue); read it, never write it.</p><h2 id="shipped-channels" tabindex="-1">Shipped channels <a class="header-anchor" href="#shipped-channels" aria-label="Permalink to &quot;Shipped channels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Package</th><th>In</th><th>Out</th></tr></thead><tbody><tr><td><code>httpChannel()</code>, <code>mcpChannel()</code></td><td><a href="/guide/http"><code>@chamvi/http</code></a></td><td>REST <code>POST /agents/:name/runs</code>, MCP <code>run_&lt;agent&gt;</code> (served by the app&#39;s routes)</td><td>none</td></tr><tr><td><code>webhookChannel({ auth })</code></td><td><a href="/guide/http#channels"><code>@chamvi/http</code></a></td><td><code>POST /channels/webhook/&lt;agent&gt;&lt;path&gt;</code></td><td>none</td></tr><tr><td><code>cronChannel()</code></td><td><a href="/guide/scheduler"><code>@chamvi/channel-cron</code></a></td><td>ticks from <code>start()</code></td><td>none</td></tr><tr><td><code>githubChannel({ app })</code></td><td><a href="/deployment/github-app"><code>@chamvi/github</code></a></td><td>signed deliveries at <code>POST /channels/github</code></td><td>a comment on an issue or pull request (<code>owner/repo#n</code>), deduplicated by a hidden marker</td></tr><tr><td><code>openclawChannel({ ... })</code></td><td><a href="/deployment/openclaw"><code>@chamvi/channel-openclaw</code></a></td><td>none</td><td>an OpenClaw chat through its hooks endpoint, deduplicated by <code>Idempotency-Key</code></td></tr><tr><td><code>chatChannel({ ... })</code></td><td><a href="/reference/chat"><code>@chamvi/chat</code></a></td><td>Chat SDK adapters: webhooks at <code>POST /channels/chat/&lt;adapter&gt;</code>, socket messages from <code>start()</code></td><td>a text message in the chat (approvals as a UI link), at least once</td></tr><tr><td><code>createWhatsAppChat({ ... })</code></td><td><a href="/deployment/whatsapp"><code>@chamvi/chat-whatsapp</code></a></td><td>WhatsApp Web socket messages from <code>start()</code> (a <code>chatChannel()</code> with the WhatsApp platform hooks)</td><td>a text message in the WhatsApp chat, at least once</td></tr><tr><td><code>createDiscordChat({ ... })</code></td><td><a href="/deployment/discord"><code>@chamvi/chat-discord</code></a></td><td>Discord Gateway messages from <code>start()</code> (a <code>chatChannel()</code> with the Discord platform hooks)</td><td>a text message in the Discord channel or thread over REST, without pings, at least once</td></tr><tr><td><code>consoleChannel({ name?, write? })</code></td><td><code>@chamvi/core</code></td><td>none</td><td>one header line per message, the body lines and, for an approval, until when it waits (default <code>console.log</code>); never throws</td></tr></tbody></table><h2 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h2><p><code>dispatch()</code> also takes files for the model, <code>attachments: [{ mediaType, filename?, data }]</code> with <code>data</code> a <code>Uint8Array</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> withFile = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    trigger: </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: </span><span style="color:#E7C58C;">&#39;http&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#DCE9F2;">, issue: </span><span style="color:#E7C58C;">43</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#7F95A6;">    // stored as artifacts of the run; the model gets them as file parts</span></span>
<span class="line"><span style="color:#DCE9F2;">    attachments: [{</span></span>
<span class="line"><span style="color:#DCE9F2;">        mediaType: </span><span style="color:#E7C58C;">&#39;image/png&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        filename: </span><span style="color:#E7C58C;">&#39;crash.png&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        data: </span><span style="color:#8FD0F2;">new</span><span style="color:#DCE9F2;"> Uint8Array(</span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> readFile(</span><span style="color:#E7C58C;">&#39;crash.png&#39;</span><span style="color:#DCE9F2;">)),</span></span>
<span class="line"><span style="color:#DCE9F2;">    }],</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> run = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> engine.getRun(withFile.runId);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#DCE9F2;">run?.trigger.attachments; </span><span style="color:#7F95A6;">// [{ id, runId, agent, mediaType: &#39;image/png&#39;, filename: &#39;crash.png&#39;, size, createdAt }]</span></span></code></pre></div><p>Each attachment is checked before anything is written (<code>mediaType</code> of the form <code>type/subtype</code> without parameters, <code>data</code> a <code>Uint8Array</code>; <code>ValidationError</code> otherwise), then stored as an <a href="/guide/agents#files">artifact</a> of the run, after the idempotency check (a deduplicated dispatch stores nothing) and before the run is created. The run&#39;s <code>trigger.attachments</code> holds their metadata. The first user message then carries the rendered envelope as text followed by one file part per attachment, so a model that reads images or PDFs gets them directly. Attachment ids are time-ordered UUIDs v7 generated in the order given, so the run&#39;s artifacts list in that order. A crash between storing the files and creating the run leaves orphan artifacts; nothing purges them yet. Two dispatches that race to create the run of the same reserved idempotency key (its first run was never created) write to the same ids, so the second write of each file is a no-op and the run names exactly the files that were stored; only a racing dispatch with more files than the winner leaves its extra files listed among the run&#39;s artifacts.</p><p>Over HTTP, <code>POST /agents/:name/runs</code> takes the same list with <code>data</code> as base64 (see <a href="/guide/http#files">HTTP API</a>).</p><h2 id="idempotency-keys" tabindex="-1">Idempotency keys <a class="header-anchor" href="#idempotency-keys" aria-label="Permalink to &quot;Idempotency keys&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> first = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#DCE9F2;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#7F95A6;">    // where the run came from on its channel; ctx.channels.findOne() answers there</span></span>
<span class="line"><span style="color:#DCE9F2;">    address: </span><span style="color:#E7C58C;">&#39;acme/app#42&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#7F95A6;">    // a redelivery with the same key returns the same run</span></span>
<span class="line"><span style="color:#DCE9F2;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#7F95A6;">    // one run at a time per issue</span></span>
<span class="line"><span style="color:#DCE9F2;">    concurrencyKey: </span><span style="color:#E7C58C;">&#39;acme/app#42&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> again = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> engine.dispatch({</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    trigger: </span><span style="color:#E7C58C;">&#39;webhook:/issues&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channel: </span><span style="color:#E7C58C;">&#39;webhook&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    payload: { repo: </span><span style="color:#E7C58C;">&#39;acme/app&#39;</span><span style="color:#DCE9F2;">, issue: </span><span style="color:#E7C58C;">42</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">    idempotencyKey: </span><span style="color:#E7C58C;">&#39;delivery-7f3a&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#DCE9F2;">again.runId === first.runId; </span><span style="color:#7F95A6;">// true</span></span>
<span class="line"><span style="color:#DCE9F2;">again.deduplicated; </span><span style="color:#7F95A6;">// true</span></span></code></pre></div><p>With an <code>idempotencyKey</code>, <code>dispatch()</code> claims the key in the store under the scope <code>&lt;agent&gt;:&lt;channel&gt;</code> (for example <code>triage:webhook</code>) for 7 days. The first dispatch creates the run. Every later dispatch with the same agent, channel and key returns the existing run id with <code>deduplicated: true</code>, and no new run is created.</p><p>A dispatch with an <a href="#the-envelope">invoker</a> claims the key under <code>&lt;agent&gt;:&lt;channel&gt;:&lt;kind&gt;:&lt;id&gt;</code> instead (<code>kind</code> and <code>id</code> URI-encoded). Keys are then per invoker: the same invoker&#39;s retry is deduplicated, while another invoker sending the same key gets a run of its own and never learns about the first.</p><p>Use a key that is stable across redeliveries: a GitHub delivery id, a cron subscription plus its scheduled time, or a key your client sends.</p><p>If the store claimed the key but the run was never created (for example <code>runs.insert</code> failed right after the claim), the next dispatch with that key creates the run under the reserved id. <code>runs.insert</code> is insert-if-absent, so concurrent dispatches create it once.</p><h2 id="concurrency-keys" tabindex="-1">Concurrency keys <a class="header-anchor" href="#concurrency-keys" aria-label="Permalink to &quot;Concurrency keys&quot;">​</a></h2><p>A run with a <code>concurrencyKey</code> starts only when no other run of the same agent with the same key is <code>running</code>, <code>waiting</code> or <code>interrupted</code>. Runs with different keys, and runs without a key, may run in parallel within the engine&#39;s local slots and any shared agent/subscription <code>concurrencyMaxRuns</code> ceilings. See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p><p>Typical keys: one per repository, issue or pull request (<code>acme/app#42</code>), or one per mailbox.</p>`,48)])])}const u=e(t,[["render",l]]);export{y as __pageData,u as default};
